#!/usr/bin/env python3
"""Create original empty demo inputs; never download a third-party catalog."""
import json,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
SHAPES={'packages/api/data/_maintained/series-releases.json': 'object', 'packages/api/data/affiliates/partners.json': 'object', 'packages/api/data/anime/characters.json': 'array', 'packages/api/data/anime/logos.json': 'array', 'packages/api/data/anime/series.json': 'array', 'packages/api/data/boardgames/games.json': 'array', 'packages/api/data/boardgames/publishers.json': 'array', 'packages/api/data/cartoons/characters.json': 'array', 'packages/api/data/cartoons/logos.json': 'array', 'packages/api/data/cartoons/series.json': 'array', 'packages/api/data/comics/characters.json': 'array', 'packages/api/data/comics/editions.json': 'array', 'packages/api/data/comics/logos.json': 'array', 'packages/api/data/comics/series-aliases.json': 'object', 'packages/api/data/comics/series.json': 'array', 'packages/api/data/consoles/consoles.json': 'array', 'packages/api/data/consoles/manufacturers.json': 'array', 'packages/api/data/esports/leagues.json': 'array', 'packages/api/data/esports/players.json': 'array', 'packages/api/data/esports/teams.json': 'array', 'packages/api/data/esports/titles.json': 'array', 'packages/api/data/fashion/brands.json': 'array', 'packages/api/data/fashion/items.json': 'array', 'packages/api/data/fashion/lines.json': 'array', 'packages/api/data/figures/items.json': 'array', 'packages/api/data/figures/lines.json': 'array', 'packages/api/data/figures/makers.json': 'array', 'packages/api/data/game/characters.json': 'array', 'packages/api/data/game/logos.json': 'array', 'packages/api/data/game/series.json': 'array', 'packages/api/data/lightnovels/characters.json': 'array', 'packages/api/data/lightnovels/logos.json': 'array', 'packages/api/data/lightnovels/series.json': 'array', 'packages/api/data/manga/characters.json': 'array', 'packages/api/data/manga/logos.json': 'array', 'packages/api/data/manga/series.json': 'array', 'packages/api/data/media/manifest.json': 'object', 'packages/api/data/modelkits/items.json': 'array', 'packages/api/data/modelkits/lines.json': 'array', 'packages/api/data/modelkits/makers.json': 'array', 'packages/api/data/ost/albums.json': 'array', 'packages/api/data/ost/artists.json': 'array', 'packages/api/data/plush/items.json': 'array', 'packages/api/data/plush/lines.json': 'array', 'packages/api/data/plush/makers.json': 'array', 'packages/api/data/pod/affiliates.json': 'object', 'packages/api/data/pod/brands.json': 'array', 'packages/api/data/pod/print-methods.json': 'array', 'packages/api/data/pod/products.json': 'array', 'packages/api/data/pod/providers.json': 'array', 'packages/api/data/service-accounts.json': 'object', 'packages/api/data/tcg/card-shards.json': 'object', 'packages/api/data/tcg/cards.json': 'array', 'packages/api/data/tcg/games.json': 'array', 'packages/api/data/tcg/sets.json': 'array'}
for name,kind in SHAPES.items():
 p=ROOT/name
 if p.exists():continue
 p.parent.mkdir(parents=True,exist_ok=True)
 value={} if kind=='object' else []
 if name.endswith('/card-shards.json'):value={'version':1,'files':[],'totalCards':0,'totalExtraCards':0}
 if name.endswith('/affiliates/partners.json'):value={'version':1,'partners':[]}
 p.write_text(json.dumps(value,indent=2)+'\n')
print('Original empty demo inputs ready; no upstream data or media downloaded.')
